import sys, os, numpy as np
sys.path.append('storage/noesis')
try:
    import cross_lineage_compare as CLC
except Exception:
    CLC = None
try:
    from validate_packing import load_saved_best
except Exception:
    load_saved_best = None

N = 26

def grid_plus_hole_seed(r0=0.1 - 1e-8, eps=1e-8):
    coords = [0.1,0.3,0.5,0.7,0.9]
    centers = [[x,y] for x in coords for y in coords]
    d = float(np.linalg.norm(np.array([0.2,0.2]) - np.array([0.1,0.1])))
    r_hole = d - r0 - eps
    return np.array(centers, float), np.array([r0]*25 + [r_hole], float)

def construct_packing():
    # Return our baseline packing (no change)
    if load_saved_best is not None:
        c, r = load_saved_best()
    else:
        c, r = None, None
    if c is None:
        c, r = grid_plus_hole_seed()

    # Cross-lineage Jaccard comparisons (read-only)
    if CLC is not None:
        try:
            CLC.compare_against('aletheia', tol=1e-8, out_dir='storage/noesis/exports')
        except Exception:
            pass
        try:
            CLC.compare_against('inquire', tol=1e-8, out_dir='storage/noesis/exports')
        except Exception:
            pass

    return c.astype(float), r.astype(float)
